MATCH (v:PlantItem {tag: 'V-201'})-[:measured_by]->(i:PlantItem)
RETURN DISTINCT i.tag AS tag
ORDER BY tag;

MATCH (t:PlantItem {tag: 'TK-102'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem)<-[:send_signal_to*1..]-(c:ProcessControlFunction)
RETURN DISTINCT c.tag AS tag
ORDER BY tag;

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'LALL-1028'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:GlobeValve {unit_id: '2'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-203'}), (b:PlantItem {tag: 'V-202'}), (blocked:PlantItem {tag: 'GTV-2007'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> blocked AND y <> blocked)+ (b)
       } AS reachable

MATCH (a:PlantItem {tag: 'E-201'}), (b:PlantItem {tag: 'E-203'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-102'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-102'}), (b:PlantItem {tag: 'E-201'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'CHV-1003')+ (b)
} AS can_flow_without_CHV1003

MATCH (:Equipment {tag: 'E-203'})-[:measured_by]->(i:PlantItem)
RETURN i.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:SwingCheckValve {unit_id: '1'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-102'})-[:line_to*1..]->(v:Valve)
WHERE EXISTS { (v)-[:line_to*1..]->(e:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-101'}), (b:PlantItem {tag: 'P-102'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'TK-102'}), (b:PlantItem {tag: 'E-202'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'P-101' AND y.tag <> 'P-101')* (b)
       } AS can_flow_without_P_101

MATCH (a:PlantItem {tag: 'P-101'}), (b:PlantItem {tag: 'E-203'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x.tag <> 'GTV-1003' AND y.tag <> 'GTV-1003')+ (b)
} AS reachable_without_GTV_1003
